$ErrorActionPreference='Stop';$root=Resolve-Path(Join-Path $PSScriptRoot '../..');Set-Location $root
$settings=@{};Get-Content .env|?{$_-match'^\s*([^#=\s]+)=(.*)$'}|%{$settings[$matches[1]]=$matches[2].Trim().Trim('"').Trim("'")};$login=Invoke-RestMethod -Method Post http://127.0.0.1:8080/api/v1/auth/token -ContentType application/json -Body(@{username=$settings.PLATFORM_BOOTSTRAP_USER;password=$settings.PLATFORM_BOOTSTRAP_PASSWORD}|ConvertTo-Json -Compress);$admin=@{Authorization="Bearer $($login.access_token)"}
function B64([byte[]]$v){[Convert]::ToBase64String($v).TrimEnd('=').Replace('+','-').Replace('/','_')};function Foreign{$n=[DateTimeOffset]::UtcNow.ToUnixTimeSeconds();$h=B64([Text.Encoding]::UTF8.GetBytes('{"alg":"HS256","typ":"JWT"}'));$b=B64([Text.Encoding]::UTF8.GetBytes((@{iss='security-platform';aud='security-platform-api';sub='foreign';tid=[guid]::NewGuid().ToString();per=@('platform:admin');pty='user';iat=$n;exp=$n+600;jti=[guid]::NewGuid().ToString('N')}|ConvertTo-Json -Compress)));$m=[Security.Cryptography.HMACSHA256]::new([Text.Encoding]::UTF8.GetBytes($settings.PLATFORM_JWT_SIGNING_KEY));try{$s=B64($m.ComputeHash([Text.Encoding]::ASCII.GetBytes("$h.$b")))}finally{$m.Dispose()};@{Authorization="Bearer $h.$b.$s"}}
function Status($method,$path,$headers=$admin,$body=$null){try{$a=@{Method=$method;Uri="http://127.0.0.1:8080$path";Headers=$headers;UseBasicParsing=$true};if($body){$a.ContentType='application/json';$a.Body=[Text.Encoding]::UTF8.GetBytes(($body|ConvertTo-Json -Depth 40 -Compress))};[int](Invoke-WebRequest @a).StatusCode}catch{[int]$_.Exception.Response.StatusCode}}
