$pass=$checks.authorizedCollection-eq200-and$checks.foreignCollection-eq404-and$checks.wrongEndpoint-in@(400,404)-and$checks.arbitraryPath-in@(400,409)-and$checks.traversal-eq400-and$checks.volumeRoot-eq400-and$checks.symlink-eq400-and$checks.hardlink-eq400-and$checks.recursive-eq400-and$checks.hugeEventLog-eq400-and$checks.hugeRegistry-eq400-and$checks.forgedProfile-eq400-and$checks.itemGuess-eq404-and$checks.foreignManifest-eq404-and$checks.objectGuess-eq404-and$checks.signedUrlMisuse-eq404-and$checks.genericBypass-eq400-and$checks.forgedApproval-eq404;$report=[ordered]@{schemaVersion='sprint22-api-security.v1';capturedAt=[DateTimeOffset]::UtcNow;checks=$checks;unitCovered=@('profile mutation after approval','duplicate delivery','cancellation race','storage output bounds','result spoofing','manifest hash integrity');passed=$pass};$report|ConvertTo-Json -Depth 30|Set-Content artifacts/sprint22-api-security.json -Encoding utf8;$report|ConvertTo-Json -Depth 30;if(!$pass){exit 1}
